/**
 * Builds a small rocket as a THREE.Group:
 * - cone nose on top
 * - cylinder body
 * - three fins around the base
 */
export function createRocket() {
  const rocket = new THREE.Group();
  rocket.name = 'Rocket';

  const bodyMaterial = new THREE.MeshStandardMaterial({ color: 0xdedede });
  const noseMaterial = new THREE.MeshStandardMaterial({ color: 0xcc2222 });
  const finMaterial = new THREE.MeshStandardMaterial({ color: 0x2244cc });

  // Body: cylinder along +Y
  const body = new THREE.Mesh(
    new THREE.CylinderGeometry(0.5, 0.5, 2, 16),
    bodyMaterial
  );
  body.name = 'Body';
  body.position.y = 1;
  rocket.add(body);

  // Nose: cone on top of the body
  const nose = new THREE.Mesh(
    new THREE.ConeGeometry(0.5, 0.8, 16),
    noseMaterial
  );
  nose.name = 'Nose';
  nose.position.y = 2.4;
  rocket.add(nose);

  // Three fins spaced 120 degrees apart
  const finShape = new THREE.Shape();
  finShape.moveTo(0, 0);
  finShape.lineTo(0.6, -0.2);
  finShape.lineTo(0.6, -0.8);
  finShape.lineTo(0, -0.8);
  finShape.closePath();

  const finGeometry = new THREE.ExtrudeGeometry(finShape, {
    depth: 0.06,
    bevelEnabled: false
  });

  for (let i = 0; i < 3; i++) {
    const fin = new THREE.Mesh(finGeometry, finMaterial);
    fin.name = `Fin${i + 1}`;
    const angle = (i / 3) * Math.PI * 2;
    fin.position.set(Math.cos(angle) * 0.5, 0.4, Math.sin(angle) * 0.5);
    fin.rotation.y = -angle + Math.PI / 2;
    rocket.add(fin);
  }

  return rocket;
}
