/**
 * Minimal FileReader polyfill for Node. The GLTFExporter only touches
 * FileReader to read a Blob as an ArrayBuffer (or data URL). Node's global
 * Blob already exposes arrayBuffer()/text(), so we can implement the two
 * read methods the exporter uses synchronously-then-async, firing
 * `onloadend` like browsers do.
 */
class MinimalFileReader {
  constructor() {
    this.result = null;
    this.onloadend = null;
    this.onerror = null;
  }

  _finish(result) {
    Promise.resolve().then(() => {
      this.result = result;
      if (typeof this.onloadend === 'function') this.onloadend({ target: this });
    });
  }

  readAsArrayBuffer(blob) {
    blob.arrayBuffer().then(
      (buf) => this._finish(buf),
      (err) => typeof this.onerror === 'function' && this.onerror(err)
    );
  }

  readAsDataURL(blob) {
    blob.arrayBuffer().then(
      (buf) => {
        const bytes = new Uint8Array(buf);
        let bin = '';
        const CHUNK = 0x8000;
        for (let i = 0; i < bytes.length; i += CHUNK) {
          bin += String.fromCharCode(...bytes.subarray(i, i + CHUNK));
        }
        this._finish(`data:${blob.type || 'application/octet-stream'};base64,${btoa(bin)}`);
      },
      (err) => typeof this.onerror === 'function' && this.onerror(err)
    );
  }
}

if (typeof globalThis.FileReader === 'undefined') {
  globalThis.FileReader = MinimalFileReader;
}

/**
 * Exports a three.js object graph to a binary GLB ArrayBuffer.
 * @param {THREE.Object3D} object
 * @returns {Promise<ArrayBuffer>}
 */
export function toGLB(object) {
  return new Promise((resolve, reject) => {
    new GLTFExporter().parse(
      object,
      (result) => resolve(result),
      (error) => reject(error),
      { binary: true }
    );
  });
}

const GLB_HEADER_BYTES = 12;
const MAGIC_GLTF = 0x46546c67; // "glTF" little-endian
const CHUNK_TYPE_JSON = 0x4e4f534a;
const CHUNK_TYPE_BIN = 0x004e4942;

/**
 * Parses a GLB container header + chunk table.
 * @param {ArrayBuffer} buf
 */
export function parseGLBHeader(buf) {
  const view = new DataView(buf);
  const magic = view.getUint32(0, true);
  const version = view.getUint32(4, true);
  const totalLength = view.getUint32(8, true);

  let offset = GLB_HEADER_BYTES;
  const chunks = [];
  while (offset < totalLength) {
    const chunkLength = view.getUint32(offset, true);
    const chunkType = view.getUint32(offset + 4, true);
    chunks.push({
      type: chunkType,
      typeHex: `0x${chunkType.toString(16).padStart(8, '0')}`,
      isJson: chunkType === CHUNK_TYPE_JSON,
      isBin: chunkType === CHUNK_TYPE_BIN,
      length: chunkLength,
      dataOffset: offset + 8,
      // JSON chunk data as text when applicable
      json:
        chunkType === CHUNK_TYPE_JSON
          ? JSON.parse(new TextDecoder().decode(new Uint8Array(buf, offset + 8, chunkLength)))
          : null,
    });
    offset += 8 + chunkLength;
  }

  return { magic, version, totalLength, byteLength: buf.byteLength, chunks };
}

export { MAGIC_GLTF, CHUNK_TYPE_JSON, CHUNK_TYPE_BIN };
