result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "test/glb.test.js", "content": "import { describe, it, expect, beforeAll } from 'vitest';
import { mkdirSync, writeFileSync, statSync } from 'node:fs';
import { createRocket } from '../src/asset.js';
import { toGLB, parseGLBHeader, MAGIC_GLTF, CHUNK_TYPE_JSON, CHUNK_TYPE_BIN } from '../src/glb.js';

const OUT_DIR = new URL('../out/', import.meta.url).pathname;
const OUT_FILE = `${OUT_DIR}rocket.glb`;

let glb;
let header;

beforeAll(async () => {
  const rocket = createRocket();
  glb = await toGLB(rocket);
  header = parseGLBHeader(glb);
});

describe('GLB container format', () => {
  it('has the "glTF" magic (0x46546C67)', () => {
    expect(header.magic).toBe(MAGIC_GLTF);
    expect(header.magic).toBe(0x46546c67);
  });

  it('is GLB version 2', () => {
    expect(header.version).toBe(2);
  });

  it('declares a total length equal to the actual buffer size', () => {
    expect(header.totalLength).toBe(glb.byteLength);
    // sanity: total covers all chunks exactly
    const consumed = 12 + header.chunks.reduce((n, c) => n + 8 + c.length, 0);
    expect(consumed).toBe(glb.byteLength);
  });
});

describe('GLB chunks', () => {
  it('first chunk is JSON and parses with asset.version "2.0"', () => {
    expect(header.chunks.length).toBeGreaterThanOrEqual(2);
    const json = header.chunks[0];
    expect(json.type).toBe(CHUNK_TYPE_JSON);
    expect(json.type).toBe(0x4e4f534a);
    expect(json.json.asset.version).toBe('2.0');
  });

  it('second chunk is BIN and chunk lengths are 4-byte aligned', () => {
    const bin = header.chunks[1];
    expect(bin.type).toBe(CHUNK_TYPE_BIN);
    expect(bin.type).toBe(0x004e4942);
    for (const chunk of header.chunks) {
      expect(chunk.length % 4).toBe(0);
    }
  });
});

describe('scene contents', () => {
  let parsed;

  beforeAll(() => {
    parsed = JSON.parse(
      new TextDecoder().decode(new Uint8Array(glb, header.chunks[0].dataOffset, header.chunks[0].length))
    );
  });

  it('lists at least 4 meshes or a node tree with 4 mesh nodes', () => {
    const meshCount = Array.isArray(parsed.meshes) ? parsed.meshes.length : 0;
    const meshNodes = Array.isArray(parsed.nodes)
      ? parsed.nodes.filter((n) => n.mesh !== undefined).length
      : 0;
    expect(meshCount >= 4 || meshNodes >= 4).toBe(true);
  });
});

describe('file export', () => {
  it('writes out/rocket.glb whose size matches the buffer', async () => {
    mkdirSync(OUT_DIR, { recursive: true });
    writeFileSync(OUT_FILE, Buffer.from(glb));
    const { size } = statSync(OUT_FILE);
    expect(size).toBe(glb.byteLength);
    expect(size).toBe(header.totalLength);
  });
});
"})
